145	            watches.saveAndFlush(new PersonWatch(sheetId, person.getId(), user));
146	            audit.recordOnCommit("PERSON_WATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
147	        } else if (watches.deleteByPersonIdAndUserName(person.getId(), user) > 0) {
148	            audit.recordOnCommit("PERSON_UNWATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
