204	    /** Add a person to the sheet (the sheet is created first if it was never loaded); {@code contact}
205	     *  (trimmed and lower-cased, null: none) is refused when another person on the sheet has it. */
206	    @Transactional
207	    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
208	        sheets.load(sheetId, user);
209	        RollupService.Snapshot before = rollup.snapshot(sheetId);
210	        String trimmed = name.trim();
211	        requireUnusedName(sheetId, null, trimmed);
212	        requireUnusedContact(sheetId, null, contact);
213	        Person person;
214	        try {
215	            Person fresh = new Person(sheetId, trimmed, grade);
216	            fresh.setTerms(terms);
217	            fresh.setContact(contact);
218	            person = people.saveAndFlush(fresh);
219	        } catch (DataIntegrityViolationException e) {
220	            throw inUse(e); // added by another user at the same moment
221	        }
222	        record("PERSON_ADDED", sheetId, user, person, sheets.today(sheetId),
223	                (terms == null ? "" : termsField(terms)) + (contact == null ? "" : contactField(contact)));
224	        rollup.recordChanges(sheetId, user, before);
225	        return person;
226	    }
