228	    /** Save a person; refused when {@code version} (the one the editor loaded) is no longer the stored one.
229	     *  The grade is recorded from {@code gradeFrom} (null: the sheet's today), keeping those already
230	     *  recorded; with no from-date, a grade the same as the one in force on the sheet's today records nothing.
231	     *  The person's own terms become {@code terms} (null: none), and their contact {@code contact}
232	     *  (null: none), refused when another person on the sheet has it. */
233	    @Transactional
234	    public Person update(String sheetId, String user, long id, Long version, String name, String grade,
235	            LocalDate gradeFrom, Integer terms, String contact) {
236	        Person person = people.findByIdAndSheetId(id, sheetId)
237	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
238	        if (version == null || version != person.getVersion()) {
239	            throw savedByAnother();
240	        }
241	        RollupService.Snapshot before = rollup.snapshot(sheetId);
242	        String trimmed = name.trim();
243	        requireUnusedName(sheetId, id, trimmed);
244	        requireUnusedContact(sheetId, id, contact);
245	        person.setName(trimmed);
246	        boolean termsChanged = !Objects.equals(terms, person.getTerms());
247	        person.setTerms(terms);
248	        boolean contactChanged = !Objects.equals(contact, person.getContact());
249	        person.setContact(contact);
250	        LocalDate today = sheets.today(sheetId);
251	        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
252	            person.recordGrade(grade, gradeFrom != null ? gradeFrom : today);
253	        }
254	        try {
255	            people.flush();
256	        } catch (DataIntegrityViolationException e) {
257	            throw inUse(e); // taken by another user at the same moment
258	        } catch (ObjectOptimisticLockingFailureException e) {
259	            throw savedByAnother(); // saved by another user at the same moment
260	        }
261	        record("PERSON_EDITED", sheetId, user, person, today,
262	                (termsChanged ? termsField(terms) : "") + (contactChanged ? contactField(contact) : ""));
263	        rollup.recordChanges(sheetId, user, before);
264	        return person;
265	    }
