267	    /** Give each of the people of {@code ids}, in list order, {@code grade} from {@code gradeFrom}
268	     *  (null: the sheet's today) as saving them in the person form would, each written with its
269	     *  PERSON_EDITED and rollup lines; all or none. Refused (404) when any is not on the sheet. */
270	    @Transactional
271	    public int grade(String sheetId, String user, List<Long> ids, String grade, LocalDate gradeFrom) {
272	        Set<Long> wanted = Set.copyOf(ids);
273	        List<Person> chosen = people.findBySheetIdOrderByIdAsc(sheetId).stream()
274	                .filter(p -> wanted.contains(p.getId())).toList();
275	        if (chosen.size() != wanted.size()) {
276	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person");
277	        }
278	        LocalDate today = sheets.today(sheetId);
279	        for (Person person : chosen) {
280	            RollupService.Snapshot before = rollup.snapshot(sheetId);
281	            if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
282	                person.recordGrade(grade, gradeFrom != null ? gradeFrom : today);
283	            }
284	            try {
285	                people.flush();
286	            } catch (ObjectOptimisticLockingFailureException e) {
287	                throw savedByAnother(); // saved by another user at the same moment
288	            }
289	            record("PERSON_EDITED", sheetId, user, person, today, "");
290	            rollup.recordChanges(sheetId, user, before);
291	        }
292	        return chosen.size();
293	    }
