332	    /** Merge a person into another person on the sheet, as a steward: the merged person's claims
333	     *  move to the other (numbers and dates kept, listed after the other's in the order they were
334	     *  added, each unbound from any statement), their name and aliases become the other's aliases,
335	     *  their patrons are added to the other's (not the other themselves, no repeats), anyone naming
336	     *  them as patron names the other instead (no repeats), and their pool memberships move to the
337	     *  other (shares added where the other is a member already). Their statements, holds, watchers
338	     *  and contact go with them. Refused (404) for a person not on the sheet, (403) unless the user
339	     *  acts as a steward, (422) for the same person, either of them retired, or a pool share added
340	     *  past 100.00. */
341	    @Transactional
342	    public Person merge(String sheetId, String user, long id, long intoId) {
343	        Person from = people.findForUpdate(id, sheetId)
344	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
345	        Person into = people.findForUpdate(intoId, sheetId)
346	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
347	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
348	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may merge people");
349	        }
350	        if (from.getId().equals(into.getId())) {
351	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A person cannot be merged into themselves");
352	        }
353	        if (from.isRetired() || into.isRetired()) {
354	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A retired person cannot be merged");
355	        }
356	        RollupService.Snapshot before = rollup.snapshot(sheetId);
357	
358	        // pool memberships: moved, or the share added to the other's
359	        for (PoolMember member : poolMembers.findByPersonIdOrderByIdAsc(from.getId())) {
360	            var theirs = poolMembers.findByPoolIdAndPersonId(member.getPoolId(), into.getId());
361	            if (theirs.isPresent()) {
362	                BigDecimal share = theirs.get().getShare().add(member.getShare());
363	                if (share.compareTo(BigDecimal.valueOf(100)) > 0) {
364	                    throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
365	                            "The merged shares would be over 100.00 in a pool");
366	                }
367	                theirs.get().setShare(share);
368	                poolMembers.delete(member);
369	            } else {
370	                member.setPersonId(into.getId());
371	            }
372	        }
373	        poolMembers.flush();
374	
375	        // claims: moved, listed after the other's in the order they were added, unbound
376	        long listed = claims.findLastListed(sheetId);
377	        List<Claim> moved = claims.findByPersonForUpdate(from.getId(), sheetId).stream()
378	                .sorted(Comparator.comparing(Claim::getId)).toList();
379	        for (Claim claim : moved) {
380	            claim.setPersonId(into.getId());
381	            claim.setListed(++listed);
382	            claim.unbind();
383	        }
384	        claims.flush();
385	
386	        // patrons: the merged person's added to the other's; those naming the merged person name the other
387	        Set<Long> intoPatrons = new LinkedHashSet<>(patronIds(into.getId()));
388	        List<PersonPatron> theirPatrons = patrons.findByPersonIdOrderByIdAsc(from.getId());
389	        List<PersonPatron> namingThem = patrons.findByPatronIdOrderByIdAsc(from.getId());
390	        for (PersonPatron named : theirPatrons) {
391	            if (!named.getPatronId().equals(into.getId()) && intoPatrons.add(named.getPatronId())) {
392	                patrons.save(new PersonPatron(sheetId, into.getId(), named.getPatronId()));
393	            }
394	        }
395	        for (PersonPatron naming : namingThem) {
396	            if (!naming.getPersonId().equals(into.getId())
397	                    && !naming.getPersonId().equals(from.getId())
398	                    && !patrons.existsByPersonIdAndPatronId(naming.getPersonId(), into.getId())) {
399	                patrons.save(new PersonPatron(sheetId, naming.getPersonId(), into.getId()));
400	            }
401	        }
402	        patrons.deleteAll(theirPatrons);
403	        patrons.deleteAll(namingThem);
404	        patrons.flush();
405	
406	        // statements and watchers go with them
407	        statements.deleteAll(statements.findByPersonIdOrderByIdAsc(from.getId()));
408	        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
409	        statements.flush();
410	        watches.flush();
411	
412	        String fromName = from.getName();
413	        List<String> fromAliases = from.getAliases();
414	        people.delete(from);
415	        people.flush();
416	        into.addAlias(fromName);
417	        fromAliases.forEach(into::addAlias);
418	        try {
419	            people.flush();
420	        } catch (ObjectOptimisticLockingFailureException e) {
421	            throw savedByAnother(); // saved by another user at the same moment
422	        }
423	        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + user + " from=" + fromName
424	                + " into=" + into.getName());
425	        rollup.recordChanges(sheetId, user, before);
426	        return into;
427	    }
