429	    /** Transfer a person to another sheet (created first if it was never loaded), as a steward: they
430	     *  arrive with every grade they were given (and its from-date), their terms, contact and
431	     *  aliases, and their claims with their status, dates, notes, tags, frozen settled figures,
432	     *  logs and comments, listed there in the order this sheet lists them; each claim that had a number
433	     *  takes the other sheet's next one, in the order the claims were opened (by the sheet's today
434	     *  when each was opened, then by the order they were added). Figures a statement bound, batches
435	     *  and references are not carried, and their statement count starts at 0. They leave this sheet
436	     *  entirely: their statements, patron links (both ways), pool memberships and watches are
437	     *  dropped, and the numbers their claims had are never given here again. Refused (404) for a
438	     *  person not on the sheet, (403) unless the user acts as a steward or when either sheet is
439	     *  archived, (422) for a retired person or this sheet's own id, and (409) when their name, an
440	     *  alias or their contact is already on the other sheet. */
441	    @Transactional
442	    public Person transfer(String sheetId, String user, long id, String toSheetId) {
443	        Person person = people.findForUpdate(id, sheetId)
444	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
445	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
446	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may transfer people");
447	        }
448	        String target = toSheetId.trim();
449	        if (target.equals(sheetId)) {
450	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A person is transferred to another sheet");
451	        }
452	        if (person.isRetired()) {
453	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A retired person cannot be transferred");
454	        }
455	        if (sheets.archived(sheetId) || sheets.archived(target)) {
456	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The sheet is archived: nothing on it may change");
457	        }
458	        sheets.load(target, user);
459	        // held until the transaction ends, so two people cannot take the same name there at once
460	        sheets.lock(target);
461	        requireUnusedName(target, null, person.getName());
462	        person.getAliases().forEach(alias -> requireUnusedName(target, null, alias));
463	        requireUnusedContact(target, null, person.getContact());
464	
465	        RollupService.Snapshot beforeHere = rollup.snapshot(sheetId);
466	        RollupService.Snapshot beforeThere = rollup.snapshot(target);
467	
468	        Person arrived;
469	        try {
470	            arrived = people.saveAndFlush(person.transferredTo(target));
471	        } catch (DataIntegrityViolationException e) {
472	            throw inUse(e); // taken there by another user at the same moment
473	        }
474	
475	        // claims: copied oldest listed first, so they are listed there in the order they are here
476	        List<Claim> theirs = claims.findByPersonForUpdate(person.getId(), sheetId).stream()
477	                .sorted(Comparator.comparingLong(Claim::getListed)).toList();
478	        long listed = claims.findLastListed(target);
479	        Map<Claim, Claim> copies = new LinkedHashMap<>();
480	        for (Claim claim : theirs) {
481	            Claim copy = claim.transferredTo(target, arrived.getId());
482	            copy.setListed(++listed);
483	            copies.put(claim, claims.saveAndFlush(copy));
484	        }
485	        Map<Long, List<ClaimLog>> logs = new HashMap<>();
486	        for (Claim claim : theirs) {
487	            logs.put(claim.getId(), claimLog.findByClaimIdOrderByIdAsc(claim.getId()));
488	        }
489	
490	        // numbers: the other sheet's next, in the order the claims were opened
491	        Map<String, String> renumbered = new HashMap<>();
492	        List<Claim> numbered = theirs.stream().filter(c -> c.getNumber() != null)
493	                .sorted(Comparator.comparing((Claim c) -> openedOn(c, logs.get(c.getId())))
494	                        .thenComparing(Claim::getId))
495	                .toList();
496	        for (Claim claim : numbered) {
497	            Claim copy = copies.get(claim);
498	            copy.setNumber(claimService.nextNumber(target, copy.getDueBy()));
499	            claims.flush();
500	            renumbered.put(claim.getNumber(), copy.getNumber());
501	        }
502	        for (Claim copy : copies.values()) {
503	            if (copy.getCorrects() != null) {
504	                copy.setCorrects(renumbered.get(copy.getCorrects()));
505	            }
506	            if (copy.getSplitFrom() != null) {
507	                copy.setSplitFrom(renumbered.get(copy.getSplitFrom()));
508	            }
509	            claimService.keepTags(copy);
510	        }
511	        claims.flush();
512	        for (Claim claim : theirs) {
513	            Long copyId = copies.get(claim).getId();
514	            for (ClaimLog line : logs.get(claim.getId())) {
515	                claimLog.save(new ClaimLog(target, copyId, line.getStatus(), line.getBy(), line.getOn(), line.getDue()));
516	            }
517	            for (ClaimComment comment : claimComments.findByClaimIdOrderByIdAsc(claim.getId())) {
518	                claimComments.save(new ClaimComment(target, copyId, comment.getBy(), comment.getOn(), comment.getText()));
519	            }
520	        }
521	        claimLog.flush();
522	        claimComments.flush();
523	
524	        // leaving this sheet entirely; the numbers their claims had are never given here again
525	        for (Claim claim : theirs) {
526	            if (claim.getNumber() != null) {
527	                retiredNumbers.save(new RetiredNumber(sheetId, claim.getNumber()));
528	            }
529	            claimLog.deleteAll(logs.get(claim.getId()));
530	            claimComments.deleteAll(claimComments.findByClaimIdOrderByIdAsc(claim.getId()));
531	        }
532	        retiredNumbers.flush();
533	        claimLog.flush();
534	        claimComments.flush();
535	        claims.deleteAll(theirs);
536	        claims.flush();
537	        patrons.deleteAll(patrons.findByPersonIdOrderByIdAsc(person.getId()));
538	        patrons.deleteAll(patrons.findByPatronIdOrderByIdAsc(person.getId()));
539	        poolMembers.deleteAll(poolMembers.findByPersonIdOrderByIdAsc(person.getId()));
540	        statements.deleteAll(statements.findByPersonIdOrderByIdAsc(person.getId()));
541	        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(person.getId()));
542	        patrons.flush();
543	        poolMembers.flush();
544	        statements.flush();
545	        watches.flush();
546	        people.delete(person);
547	        try {
548	            people.flush();
549	        } catch (ObjectOptimisticLockingFailureException e) {
550	            throw savedByAnother(); // saved by another user at the same moment
551	        }
552	
553	        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + sheetId + " by=" + user
554	                + " name=" + person.getName() + " to=" + target);
555	        rollup.recordChanges(sheetId, user, beforeHere);
556	        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + target + " by=" + user
557	                + " name=" + arrived.getName() + " from=" + sheetId);
558	        rollup.recordChanges(target, user, beforeThere);
559	        return arrived;
560	    }
561	
562	    /** The sheet's today when the claim was opened: its first OPEN log line's, else its first
563	     *  line's, else its date. */
564	    private static LocalDate openedOn(Claim claim, List<ClaimLog> log) {
565	        return log.stream().filter(l -> l.getStatus() == ClaimStatus.OPEN).findFirst()
566	                .or(() -> log.stream().findFirst())
567	                .map(ClaimLog::getOn)
568	                .orElse(claim.getDate());
569	    }
570	
571	    /** Written with the grade in force on {@code today}, the sheet's today, then {@code extra}. */
572	    private void record(String event, String sheetId, String user, Person person, LocalDate today, String extra) {
573	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
574	                + " name=" + person.getName() + " grade=" + person.gradeOn(today) + extra);
575	    }
576	
577	    /** The terms field of a person's record: the days, empty when none. */
578	    private static String termsField(Integer terms) {
579	        return " terms=" + (terms == null ? "" : terms);
580	    }
581	
582	    /** The contact field of a person's record: the contact, empty when none. */
583	    private static String contactField(String contact) {
584	        return " contact=" + (contact == null ? "" : contact);
585	    }
586	
587	    /** Refuse a contact another person on the sheet already has; none is never refused. */
588	    private void requireUnusedContact(String sheetId, Long exceptId, String contact) {
589	        if (contact == null) {
590	            return;
591	        }
592	        boolean taken = people.findBySheetIdAndContact(sheetId, contact).stream()
593	                .anyMatch(p -> !p.getId().equals(exceptId));
594	        if (taken) {
595	            throw contactInUse();
596	        }
597	    }
598	
599	    /** A unique name or contact taken by another user at the same moment. */
600	    private static ResponseStatusException inUse(DataIntegrityViolationException e) {
601	        String message = String.valueOf(e.getMostSpecificCause().getMessage()).toUpperCase(java.util.Locale.ROOT);
602	        return message.contains("PERSON_SHEET_CONTACT") ? contactInUse() : nameInUse();
603	    }
604	
605	    /** Refuse a name another person on the sheet already has as their name or an alias (ignoring
606	     *  case); {@code exceptId} null checks against everyone, the person's own name and aliases too. */
607	    private void requireUnusedName(String sheetId, Long exceptId, String name) {
608	        boolean taken = people.findBySheetIdAndNameIgnoreCase(sheetId, name).stream()
609	                .anyMatch(p -> !p.getId().equals(exceptId))
610	                || !people.findBySheetIdAndAliasIgnoreCase(sheetId, name).isEmpty();
611	        if (taken) {
612	            throw nameInUse();
613	        }
614	    }
615	
616	    private static ResponseStatusException savedByAnother() {
617	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Saved by someone else since it was loaded");
618	    }
619	
620	    private static ResponseStatusException patronAlready() {
621	        return new ResponseStatusException(HttpStatus.CONFLICT, "Already a patron");
622	    }
623	
624	    private static ResponseStatusException contactInUse() {
625	        return new ResponseStatusException(HttpStatus.CONFLICT, "Contact already in use");
626	    }
627	
628	    private static ResponseStatusException nameInUse() {
629	        return new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use");
630	    }
631	}
