-- The sheet's parent: the id of another sheet whose rates (then its parent's, up to three levels
-- up) apply to a grade with no rate of its own in force on a date; null when blank (none). Not dated.
ALTER TABLE sheet ADD COLUMN parent VARCHAR(100);
-- A person's aliases, kept trimmed. An alias shares the names' uniqueness on the sheet (ignoring
-- case): it equals no name or alias of anyone on the sheet; the service enforces that, and
-- alias_key keeps one person from holding the same alias twice.
CREATE TABLE person_alias (
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(alias)),
    PRIMARY KEY (person_id, alias)
);
CREATE UNIQUE INDEX person_alias_key ON person_alias (person_id, alias_key);
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class QuickAddService {

    /** The grade a person the quick-add creates is given. */
    static final String NEW_PERSON_GRADE = "A";

    /** A quick-add's result: the person the claim is for (perhaps just created) and the claim. */
    public record QuickAdd(Person person, boolean personAdded, Claim claim) {
    }

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claimService;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claimService) {
        this.people = people;
        this.personService = personService;
        this.claimService = claimService;
    }

    /** Add a DRAFT claim dated the sheet's entry date (while set, else its today) with an empty note for the person with this name
     *  or alias (ignoring case and surrounding spaces), adding them with grade A first when the sheet has no
     *  such person. One change: when the claim is refused, the person is not added either. */
    @Transactional
    public QuickAdd add(String sheetId, String user, String name, BigDecimal amount) {
        String trimmed = name.trim();
        Person person = people.findBySheetIdAndNameOrAlias(sheetId, trimmed).orElse(null);
        boolean added = person == null;
        if (added) {
            person = personService.add(sheetId, user, trimmed, NEW_PERSON_GRADE, null, null);
        }
        Claim claim = claimService.add(sheetId, user, person.getId(), amount, null, "", null, null, null);
        return new QuickAdd(person, added, claim);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PasteClaimsService {

    /** A claim's amount as the claim form takes it. */
    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,13}(\\.\\d{1,2})?");

    /** The longest note the claim form takes. */
    private static final int NOTE_MAX = 1000;

    private final PersonRepository people;
    private final ClaimService claims;

    public PasteClaimsService(PersonRepository people, ClaimService claims) {
        this.people = people;
        this.claims = claims;
    }

    /** Add a DRAFT claim for each line of name,amount,date,note, in order: the name of a person on
     *  the sheet (ignoring case and surrounding spaces), an amount, a date (blank: the sheet's
     *  entry date while set, else its today) and a note that may hold commas or be absent, ending
     *  in ` #<reference>` to give the claim that reference (not part of the note); blank lines are skipped. Each line is
     *  taken by the claim form's rules; one change, so when any line is refused (400 when it is not
     *  a claim the form takes, 422 when its name is not on the sheet, else as the claim form
     *  refuses it) nothing is added. */
    @Transactional
    public List<Claim> paste(String sheetId, String user, String text) {
        List<String[]> lines = new ArrayList<>();
        for (String line : text.split("\\r?\\n|\\r")) {
            if (!line.isBlank()) lines.add(line.split(",", 4));
        }
        if (lines.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Paste at least one line");
        }
        List<Claim> added = new ArrayList<>();
        for (int i = 0; i < lines.size(); i++) {
            String[] f = lines.get(i);
            int n = i + 1;
            if (f.length < 2) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + n + ": give a name and an amount");
            }
            String name = f[0].trim();
            String amount = f[1].trim();
            String date = f.length > 2 ? f[2].trim() : "";
            String note = f.length > 3 ? f[3].trim() : "";
            String ref = null;
            int hash = note.lastIndexOf(" #");
            if (hash >= 0 && !note.substring(hash + 2).isBlank()) {
                ref = note.substring(hash + 2).trim();
                note = note.substring(0, hash).trim();
            }
            if (name.isEmpty() || !AMOUNT.matcher(amount).matches() || note.length() > NOTE_MAX) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + n + ": not a claim the form takes");
            }
            LocalDate on;
            try {
                on = date.isEmpty() ? null : LocalDate.parse(date);
            } catch (DateTimeParseException e) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Line " + n + ": the date is not yyyy-mm-dd");
            }
            Person person = people.findBySheetIdAndNameOrAlias(sheetId, name)
                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                            "Line " + n + ": no person named " + name));
            added.add(claims.add(sheetId, user, person.getId(), new BigDecimal(amount), on, note, null, ref, null));
        }
        return added;
    }
}
package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Optional;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class SheetService {

    private final SheetRepository sheets;
    private final RollupService rollup;
    private final ApplicationEventPublisher events;

    public SheetService(SheetRepository sheets, RollupService rollup, ApplicationEventPublisher events) {
        this.sheets = sheets;
        this.rollup = rollup;
        this.events = events;
    }

    /** Load a sheet by id; an id never used before starts an empty sheet, its today the real date. */
    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, LocalDate.now()));
            } catch (DataIntegrityViolationException e) {
                // another user created it at the same moment
                return sheets.findById(id).orElseThrow(() -> e);
            }
        });
    }

    /** The sheet, if it was ever loaded. */
    @Transactional(readOnly = true)
    public Optional<Sheet> find(String id) {
        return sheets.findById(id);
    }

    /** Write the changes made to a loaded sheet. */
    @Transactional
    public void flush() {
        sheets.flush();
    }

    /** The sheet's today: the date every date decision and default date on the sheet uses. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseGet(LocalDate::now);
    }

    /** The date a new claim left undated takes: the sheet's entry date while set, else its today. */
    @Transactional(readOnly = true)
    public LocalDate entryDate(String id) {
        return sheets.findById(id).map(Sheet::getEntryDateInForce).orElseGet(LocalDate::now);
    }

    /** The sheet's floor in force on its today. */
    @Transactional(readOnly = true)
    public BigDecimal floor(String id) {
        return sheets.findById(id).map(Sheet::getFloor).orElse(Sheet.DEFAULT_FLOOR);
    }

    /** The sheet's floor in force on a date: a live due of a claim dated then is at least it. */
    @Transactional(readOnly = true)
    public BigDecimal floorOn(String id, LocalDate on) {
        return sheets.findById(id).map(s -> s.floorOn(on)).orElse(Sheet.DEFAULT_FLOOR);
    }

    /** The sheet's terms in force on its today. */
    @Transactional(readOnly = true)
    public int terms(String id) {
        return sheets.findById(id).map(Sheet::getTerms).orElse(Sheet.DEFAULT_TERMS);
    }

    /** The sheet's late percent in force on its today. */
    @Transactional(readOnly = true)
    public BigDecimal latePct(String id) {
        return sheets.findById(id).map(Sheet::getLatePct).orElse(Sheet.DEFAULT_LATE_PCT);
    }

    /** The sheet's cap in force on its today: a person's due-total is at most it; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal cap(String id) {
        return sheets.findById(id).map(Sheet::getCap).orElse(null);
    }

    /** The sheet's proof threshold in force on a date; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal proofThresholdOn(String id, LocalDate on) {
        return sheets.findById(id).map(s -> s.proofThresholdOn(on)).orElse(null);
    }

    /** The proof threshold in force on a date for a grade: the grade's own when one is set, else
     *  the sheet's; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal proofThresholdFor(String id, String grade, LocalDate on) {
        return sheets.findById(id).map(s -> s.proofThresholdFor(grade, on)).orElse(null);
    }

    /** The sheet's note threshold in force on a date; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal noteThresholdOn(String id, LocalDate on) {
        return sheets.findById(id).map(s -> s.noteThresholdOn(on)).orElse(null);
    }

    /** Whether the sheet is archived: every change on it is refused. */
    @Transactional(readOnly = true)
    public boolean archived(String id) {
        return sheets.findById(id).map(Sheet::isArchived).orElse(false);
    }

    /** Whether a claim opened now is numbered within its period. */
    @Transactional(readOnly = true)
    public boolean periodNumberingOn(String id) {
        return sheets.findById(id).map(Sheet::isPeriodNumberingOn).orElse(false);
    }

    /** Take the sheet's next claim number (1 for the first), holding the sheet locked until the
     *  transaction ends so numbers are never shared and, if it rolls back, never skipped. */
    @Transactional
    public int nextClaimNumber(String id) {
        Sheet sheet = sheets.findForUpdate(id).orElseThrow();
        int number = sheet.nextClaimNumber();
        sheets.flush();
        return number;
    }

    /** Hold the sheet locked until the transaction ends, so changes checked against the rest of
     *  the sheet (such as a period that must not overlap another) are made one at a time. */
    @Transactional
    public void lock(String id) {
        sheets.findForUpdate(id).orElseThrow();
    }

    /** Change the sheet's today (the sheet is created first if it was never loaded); it has no
     *  audit line of its own; when it moves, each person's due-total on the day being left is
     *  recorded first (SNAPSHOT), then what follows from it (such as periods closed past their
     *  grace days) and then the figures it moves. */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id, user);
        lock(id);
        RollupService.Snapshot before = rollup.snapshot(id);
        if (!today.equals(sheet.getToday())) {
            rollup.recordSnapshot(id, user, before);
        }
        sheet.setToday(today);
        sheets.flush();
        events.publishEvent(new TodayChanged(id, user, today));
        rollup.recordChanges(id, user, before);
        return sheet;
    }
}
package net.officefloor.hq.app.sheet;

import java.util.List;
import java.util.Optional;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;

public interface SheetRepository extends JpaRepository<Sheet, String> {

    /** The sheet, locked so two users cannot take the same claim number at once. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select s from Sheet s where s.id = :id")
    Optional<Sheet> findForUpdate(String id);

    /** The sheets naming the sheet as their parent: its children, by id. */
    List<Sheet> findByParentOrderByIdAsc(String parent);
}
package net.officefloor.hq.app.person;

import java.util.List;
import java.util.Optional;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;

public interface PersonRepository extends JpaRepository<Person, Long> {

    /** The sheet's people in the order they were added. */
    List<Person> findBySheetIdOrderByIdAsc(String sheetId);

    Optional<Person> findByIdAndSheetId(Long id, String sheetId);

    /** The sheet's people with this name, ignoring case. */
    List<Person> findBySheetIdAndNameIgnoreCase(String sheetId, String name);

    /** The sheet's people with this alias, ignoring case. */
    @Query("select p from Person p join p.aliases a where p.sheetId = :sheetId and lower(a) = lower(:alias)")
    List<Person> findBySheetIdAndAliasIgnoreCase(String sheetId, String alias);

    /** The sheet's person with this name, else with this alias, ignoring case. */
    default Optional<Person> findBySheetIdAndNameOrAlias(String sheetId, String name) {
        return findBySheetIdAndNameIgnoreCase(sheetId, name).stream().findFirst()
                .or(() -> findBySheetIdAndAliasIgnoreCase(sheetId, name).stream().findFirst());
    }

    /** The sheet's people with this contact. */
    List<Person> findBySheetIdAndContact(String sheetId, String contact);

    /** The person, locked so two statements of them are taken one after the other. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select p from Person p where p.id = :id and p.sheetId = :sheetId")
    Optional<Person> findForUpdate(Long id, String sheetId);
}
