  if (ref.length > 120) {
    this.error.set('Enter a reference of up to 120 characters.');
    return;
  }
  const tags = value.tags.trim();
  if (tags.length > 1000) {
    this.error.set('Enter tags of up to 1000 characters in all.');
    return;
  }
